/// `final`) so the agent layer's `AgentTool` can extend it, mirroring pi's
/// `interface AgentTool extends Tool`.
base class Tool {
  const Tool({
    required this.name,
    required this.description,
    required this.parameters,
  });

  /// The tool's name (what the model calls).
  final String name;

  /// Human- and model-readable description of what the tool does.
  final String description;

  /// JSON Schema for the tool's arguments.
  final Map<String, dynamic> parameters;

  /// Serializes to a JSON map.
  Map<String, dynamic> toJson() => {
    'name': name,
    'description': description,
    'parameters': parameters,
  };

  /// Deserializes from a JSON map produced by [toJson].
  factory Tool.fromJson(Map<String, dynamic> json) => Tool(
    name: json['name'] as String? ?? '',
    description: json['description'] as String? ?? '',
    parameters:
        (json['parameters'] as Map<String, dynamic>?) ??
        const <String, dynamic>{},
  );
}

