55:/// Removes one retired app-seeded `<name>/SKILL.md` — and, issue #1334, the
56:/// skill directory itself when it is left EMPTY: an empty `<name>/` under
57:/// `.fah/skills` is invisible to discovery but loudly visible to an
58:/// exploring agent, reading as "skills materialize as empty directories".
59:/// The empty-dir prune also fires when the copy is already gone, so
60:/// devices retired by older builds (which left the ghost dirs behind)
61:/// repair on their next launch. A dir with surviving user files
62:/// (review -HUjo) stays.
63:Future<void> _retireSeededCopy(
64:  ExecutionEnv env,
65:  String name,
66:  bool Function(String sha256) isStale,
67:) async {
68:  try {
69:    final dir = '${env.cwd}/.fah/skills/$name';
70:    final body = (await env.readTextFile('$dir/SKILL.md')).valueOrNull;
71:    if (body != null) {
72:      if (!isStale(sha256.convert(utf8.encode(body)).toString())) return;
73:      await env.remove('$dir/SKILL.md');
74:    }
75:    final leftovers = await env.listDir(dir);
76:    if (leftovers.isOk && leftovers.valueOrNull!.isEmpty) {
77:      await env.remove(dir);
78:    }
79:  } on Object {
80:    // best-effort cleanup
81:  }
82:}
