85:  for (final entry in _staleBundledSeedFingerprints.entries) {
86:    await _retireSeededCopy(env, entry.key, entry.value.contains);
87:  }
88:  for (final entry in _staleSeedFingerprints.entries) {
89:    await _retireSeededCopy(env, entry.key, (sha) => sha == entry.value);
90:  }
